/**
 * Labeled query set for the dense-vs-sparse-vs-hybrid retrieval benchmark
 * (see docs/sparse-vs-dense-benchmark-plan.md). Labels are deterministic,
 * not guessed — every query targets one or more of the real finding titles
 * generated by dashboard/src/seed.ts's VULNERABILITY_TEMPLATES, so "is this
 * result correct" is a plain string match, not manual judgment.
 *
 * Four categories, matching the plan's own hypothesis table:
 *  - identifier: literal CWE codes or exact title phrases — sparse/keyword
 *    should have the advantage here.
 *  - paraphrase: same finding, deliberately reworded — dense should have
 *    the advantage here.
 *  - log: a fabricated log/config-dump snippet implying a finding, without
 *    using its title wording at all.
 *  - mixed: an identifier plus conceptual language in the same query.
 */
export type QueryCategory = "identifier" | "paraphrase" | "log" | "mixed";

export interface LabeledQuery {
  category: QueryCategory;
  query: string;
  /** Any finding whose title is in this list counts as a correct result. */
  correctTitles: string[];
}

